package com.rohit.inventory.config;
import io.swagger.v3.oas.models.OpenAPI; import io.swagger.v3.oas.models.Components; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.SecurityScheme; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig { @Bean OpenAPI inventoryOpenApi(){return new OpenAPI().info(new Info().title("Multi-Warehouse Inventory API").version("v1").description("JWT-protected inventory platform API. Use Authorization: Bearer <accessToken>." )).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));} }
